@interface DXLocalBackupDetail : UITableViewController
@property NSURL *url;
@end
@implementation DXLocalBackupDetail
- (void)viewDidLoad{[super viewDidLoad];self.title=@"备份详情";self.tableView.accessibilityIdentifier=@"backup.local.detail";self.tableView.rowHeight=UITableViewAutomaticDimension;}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return 4;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)index{NSDictionary *a=[NSFileManager.defaultManager attributesOfItemAtPath:self.url.path error:nil];if(index.row==0)return AICell(@"备份文件",self.url.lastPathComponent,@"archivebox");if(index.row==1)return AICell([NSByteCountFormatter stringFromByteCount:[a[NSFileSize] longLongValue] countStyle:NSByteCountFormatterCountStyleFile],[NSDateFormatter localizedStringFromDate:a[NSFileModificationDate]?:NSDate.distantPast dateStyle:NSDateFormatterMediumStyle timeStyle:NSDateFormatterShortStyle],@"clock");UITableViewCell *c=AICell(index.row==2?@"保存或分享":@"删除本机备份",index.row==2?@"导出到“文件”或其他软件":@"仅删除这个备份文件",index.row==2?@"square.and.arrow.up":@"trash");if(index.row==3)c.textLabel.textColor=UIColor.systemRedColor;return c;}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)i{[table deselectRowAtIndexPath:i animated:YES];if(i.row==2){UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[self.url] applicationActivities:nil];share.popoverPresentationController.sourceView=[table cellForRowAtIndexPath:i];[self presentViewController:share animated:YES completion:nil];}else if(i.row==3){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"删除这个本机备份？" message:@"删除后无法从此文件恢复。项目与会话原数据不会删除。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"删除" style:UIAlertActionStyleDestructive handler:^(id action){self.tableView.userInteractionEnabled=NO;NSURL *url=self.url;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSError *error=nil;[NSFileManager.defaultManager removeItemAtURL:url error:&error];dispatch_async(dispatch_get_main_queue(),^{self.tableView.userInteractionEnabled=YES;if(error)AIAlert(self,@"未删除",error.localizedDescription);else[self.navigationController popViewControllerAnimated:YES];});});}]];[self presentViewController:a animated:YES completion:nil];}}
@end
@interface DXLocalBackupsPage : UITableViewController
@property NSArray *files;
@end
@implementation DXLocalBackupsPage
- (void)viewDidLoad{[super viewDidLoad];self.title=@"本机备份";self.tableView.accessibilityIdentifier=@"backup.local.list";self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=68;}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[self reloadBackups];}
- (void)reloadBackups{UIActivityIndicatorView *spinner=[[UIActivityIndicatorView alloc]initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];[spinner startAnimating];self.tableView.backgroundView=spinner;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSString *root=[NSHomeDirectory() stringByAppendingPathComponent:@"Documents/DylixBackups"];NSMutableArray *files=[NSMutableArray new];for(NSString *name in [NSFileManager.defaultManager contentsOfDirectoryAtPath:root error:nil]){NSString *p=[root stringByAppendingPathComponent:name];NSDictionary *a=[NSFileManager.defaultManager attributesOfItemAtPath:p error:nil];if([name.pathExtension isEqual:@"dylixbak"]&&[a[NSFileType] isEqual:NSFileTypeRegular])[files addObject:@{@"url":[NSURL fileURLWithPath:p],@"bytes":a[NSFileSize]?:@0,@"date":a[NSFileModificationDate]?:NSDate.distantPast}];}[files sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [b[@"date"] compare:a[@"date"]];}];dispatch_async(dispatch_get_main_queue(),^{self.files=files;UILabel *empty=[UILabel new];empty.text=@"尚未创建本机备份";empty.textAlignment=NSTextAlignmentCenter;empty.textColor=UIColor.secondaryLabelColor;self.tableView.backgroundView=files.count?nil:empty;[self.tableView reloadData];});});}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.files.count;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *r=self.files[i.row];UITableViewCell *c=AICell([NSDateFormatter localizedStringFromDate:r[@"date"] dateStyle:NSDateFormatterMediumStyle timeStyle:NSDateFormatterShortStyle],[NSString stringWithFormat:@"%@ · %@",[NSByteCountFormatter stringFromByteCount:[r[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile],[r[@"url"] lastPathComponent]],@"archivebox");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];DXLocalBackupDetail *page=[[DXLocalBackupDetail alloc]initWithStyle:UITableViewStyleInsetGrouped];page.url=self.files[i.row][@"url"];[self.navigationController pushViewController:page animated:YES];}
@end
