- (void)dealloc{[NSNotificationCenter.defaultCenter removeObserver:self];[self.timer invalidate];if(self.inspection)[NSFileManager.defaultManager removeItemAtPath:[self.inspection[@"tree"] stringByDeletingLastPathComponent] error:nil];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.oldToolbarHidden=self.navigationController.toolbarHidden;[self.navigationController setToolbarHidden:YES animated:animated];[self attachBackupTask];}
- (void)viewDidAppear:(BOOL)animated{[super viewDidAppear:animated];[self attachBackupTask];}
- (void)viewWillDisappear:(BOOL)animated{[super viewWillDisappear:animated];[self.navigationController setToolbarHidden:self.oldToolbarHidden animated:animated];if(self.observingTask){[self.timer invalidate];self.timer=nil;}}
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];UIView *footer=self.tableView.tableFooterView;CGFloat width=self.tableView.bounds.size.width;CGFloat height=[footer systemLayoutSizeFittingSize:CGSizeMake(width,0) withHorizontalFittingPriority:UILayoutPriorityRequired verticalFittingPriority:UILayoutPriorityFittingSizeLevel].height;if(fabs(footer.frame.size.height-height)>1||fabs(footer.frame.size.width-width)>1){footer.frame=CGRectMake(0,0,width,height);self.tableView.tableFooterView=footer;}}
- (NSString *)duration:(NSTimeInterval)seconds{NSInteger n=MAX(1,(NSInteger)ceil(seconds));return n<60?[NSString stringWithFormat:@"%ld 秒",(long)n]:n<3600?[NSString stringWithFormat:@"%ld 分 %ld 秒",(long)n/60,(long)n%60]:[NSString stringWithFormat:@"%ld 小时 %ld 分",(long)n/3600,(long)(n%3600)/60];}
- (double)estimatedSeconds{unsigned long long bytes=0,files=0;for(NSString *key in self.selected){bytes+=[self.estimate[@"bytesByCategory"][key] unsignedLongLongValue];files+=[self.estimate[@"filesByCategory"][key] unsignedLongLongValue];}double seconds=bytes/(8.0*1024*1024)+files*.008+(self.encrypted?2:1);return MAX(2,seconds);}
- (void)updateSummary{
 NSDictionary *sizes=self.restore?self.inspection[@"manifest"][@"bytesByCategory"]:self.estimate[@"bytesByCategory"];unsigned long long bytes=0;NSUInteger measured=0;for(NSString *key in self.selected){if(sizes[key])measured++;bytes+=[sizes[key] unsignedLongLongValue];}
 self.summary.text=[NSString stringWithFormat:@"已选 %lu 类内容%@",(unsigned long)self.selected.count,!self.restore&&self.scanning?[NSString stringWithFormat:@" · %lu/%lu 已统计",(unsigned long)measured,(unsigned long)self.selected.count]:@""];
 self.sizeCaption.text=@"备份前大小";self.timeCaption.text=@"预计耗时";self.sizeValue.text=measured==self.selected.count?[NSByteCountFormatter stringFromByteCount:bytes countStyle:NSByteCountFormatterCountStyleFile]:measured?[NSString stringWithFormat:@"≥ %@",[NSByteCountFormatter stringFromByteCount:bytes countStyle:NSByteCountFormatterCountStyleFile]]:@"—";
