 UIButtonConfiguration *c=self.actionButton.configuration;c.title=self.busy?@"正在处理…":self.restore?@"恢复所选内容":@"立即备份";c.image=[UIImage systemImageNamed:self.busy?@"stop.circle":self.restore?@"arrow.counterclockwise":@"externaldrive.badge.plus"];self.actionButton.configuration=c;self.actionButton.enabled=self.observingTask&&self.busy?!self.progress.cancelled:!self.busy&&self.selected.count>0&&(!self.restore||self.inspection!=nil);
 if(self.busy){[self updateWorkPanel];}else{[self.actionButton showProgress:0 working:NO indeterminate:NO];if(self.restore)self.status.text=self.inspection?@"校验通过 · 恢复将在重启后执行":@"请先选择并校验备份文件";else if(self.scanFailure)self.status.text=@"统计未完成 · 下拉刷新，或直接开始备份";else self.status.text=self.scanning?@"正在统计 · 可直接开始，备份前会重新核验":@"压缩前估算 · 最终大小与耗时可能变化";}
