- (void)refreshSizes{[self loadSizes:YES];}
- (void)scanSizes{[self loadSizes:NO];}
- (void)loadSizes:(BOOL)force{__weak typeof(self) weak=self;DXLoadInventory(force,^(NSDictionary *estimate,BOOL scanning,NSError *error){typeof(self) page=weak;if(!page)return;page.scanning=scanning;page.estimate=estimate;page.scanFailure=error.localizedDescription;[page updateSummary];[page.tableView reloadData];if(!scanning)[page.refreshControl endRefreshing];});}
- (void)updateWorkPanel{
 double elapsed=MAX(0,NSProcessInfo.processInfo.systemUptime-self.startedAt),fraction=MAX(0,MIN(1,self.progress.fractionCompleted));BOOL preparing=!self.measuredWork||fraction<=0;NSString *stage=self.progress.userInfo[@"DXBackupStage"]?:@"正在准备";self.summary.text=stage;
 self.sizeCaption.text=@"已用时间";self.sizeValue.text=[self duration:elapsed];self.timeCaption.text=@"预计剩余";self.timeValue.text=!preparing&&elapsed>2&&fraction>.01?[self duration:MAX(1,elapsed*(1-fraction)/fraction)]:@"正在估算";
