 [self.actionButton showProgress:fraction working:YES indeterminate:preparing];NSNumber *files=self.progress.userInfo[@"DXBackupScannedFiles"];self.status.text=self.progress.cancelled?@"正在清理未完成文件":preparing&&files?[NSString stringWithFormat:@"已扫描 %@ 个文件 · 轻点按钮可终止",files]:self.observingTask?@"备份在本机进行 · 轻点按钮可终止":@"正在本机处理，请稍候";
}
- (void)changeMode:(UISegmentedControl *)control{if(self.busy){control.selectedSegmentIndex=self.restore?1:0;return;}self.restore=control.selectedSegmentIndex==1;self.progressView.hidden=YES;self.status.text=self.restore?@"选择备份文件，校验后选择要恢复的分类。":@"压缩前大小，不含设备凭据体积；压缩后文件大小和耗时会因内容、设备性能而变化。";[self updateSummary];[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 3;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?DXBackupCategories().count:s==1?(self.restore?1:4):1;}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return @[@"数据分类",self.restore?@"备份文件":@"加密与凭据",@"备份历史"][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{
 if(s==0)return self.restore?@"合并恢复所选分类，同名文件会被覆盖。恢复前保留原文件；重启 App 后，在会话与工具加载前执行。外部目录授权需重新选择。":@"显示压缩前数据大小，不含可选密钥及清单等开销。不包含 Linux 环境、构建缓存、设备配对与外部目录授权。预计耗时仅供参考。";
 if(s==1)return @"记住的密码仅保存在本机钥匙串，不进入备份、偏好或日志。请另行保存密码，换设备或更换签名后可能无法读取。关闭记住会清除钥匙串中的备份密码。包含凭据时必须加密。";return nil;
}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{
 if(i.section==0){NSDictionary *c=DXBackupCategories()[i.row];BOOL available=!self.restore||!self.inspection||[self.inspection[@"manifest"][@"categories"] containsObject:c[@"id"]];NSDictionary *sizes=self.restore?self.inspection[@"manifest"][@"bytesByCategory"]:self.estimate[@"bytesByCategory"];NSString *size=sizes[c[@"id"]]?[NSByteCountFormatter stringFromByteCount:[sizes[c[@"id"]] longLongValue] countStyle:NSByteCountFormatterCountStyleFile]:self.restore?@"—":self.scanning?@"统计中…":@"—";UITableViewCell *cell=AICell([NSString stringWithFormat:@"%@ · %@",c[@"name"],size],available?c[@"detail"]:@"该备份未包含此分类",@"archivebox");cell.accessoryType=[self.selected containsObject:c[@"id"]]&&available?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;cell.textLabel.enabled=available;cell.accessibilityIdentifier=[@"backup.category." stringByAppendingString:c[@"id"]];return cell;}
 if(i.section==2){UITableViewCell *c=AICell(@"本机备份",@"查看、分享或删除已创建的备份文件",@"clock.arrow.circlepath");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
 if(self.restore){UITableViewCell *c=AICell(@"选择备份文件",self.inspection?[NSString stringWithFormat:@"已校验 · %@ 个文件",@([self.inspection[@"manifest"][@"files"] count])]:@"从“文件”打开 .dylixbak",@"doc.badge.arrow.up");c.accessibilityIdentifier=@"backup.choose";return c;}
 if(i.row==1){UITableViewCell *c=AICell(@"备份密码",self.password.length?(self.hasRememberedPassword?@"已记住 · 本机钥匙串":@"本次已设置"):@"点此设置密码",@"key");c.accessibilityIdentifier=@"backup.password";return c;}
 if(i.row==3){UITableViewCell *c=AICell(@"记住备份密码",@"下次进入自动读取本机钥匙串",@"key.horizontal");UISwitch *toggle=[UISwitch new];toggle.on=self.rememberPassword;toggle.tag=2;toggle.accessibilityIdentifier=@"backup.remember";[toggle addTarget:self action:@selector(toggle:) forControlEvents:UIControlEventValueChanged];c.accessoryView=toggle;return c;}
 BOOL encryption=i.row==0;UITableViewCell *c=AICell(encryption?@"密码加密":@"包含 API 密钥与 MCP 凭据",encryption?@"保护备份内容":@"仅存入加密备份",encryption?@"lock":@"key.fill");UISwitch *toggle=[UISwitch new];toggle.on=encryption?self.encrypted:self.secrets;toggle.tag=encryption?0:1;toggle.accessibilityIdentifier=encryption?@"backup.encryption":@"backup.secrets";[toggle addTarget:self action:@selector(toggle:) forControlEvents:UIControlEventValueChanged];c.accessoryView=toggle;return c;
}
- (void)toggle:(UISwitch *)sender{if(self.busy){sender.on=!sender.on;return;}if(sender.tag==2){NSError *error=nil;BOOL ok=DXBackupSavePassword(sender.on?(self.password?:@""):@"",&error);if(!ok){sender.on=!sender.on;AIAlert(self,@"密码记忆未修改",error.localizedDescription);return;}self.rememberPassword=sender.on;self.hasRememberedPassword=sender.on&&self.password.length>0;[NSUserDefaults.standardUserDefaults setBool:sender.on forKey:@"DylixBackupRememberPassword-v1"];[self.tableView reloadData];return;}if(sender.tag==0){if(!sender.on&&self.secrets){sender.on=YES;AIAlert(self,@"需要加密",@"请先关闭包含凭据。");return;}self.encrypted=sender.on;}else{self.secrets=sender.on;if(self.secrets)self.encrypted=YES;}[self updateSummary];[self.tableView reloadData];}
- (void)usePassword:(NSString *)password{self.password=password;if(self.rememberPassword){NSError *error=nil;self.hasRememberedPassword=DXBackupSavePassword(password,&error);if(!self.hasRememberedPassword)AIAlert(self,@"密码未记住",error.localizedDescription);}}
- (void)askPassword:(BOOL)confirm completion:(void(^)(NSString *))completion{
 UIAlertController *a=[UIAlertController alertControllerWithTitle:confirm?@"设置备份密码":@"输入备份密码" message:confirm?@"至少 8 个字符，请妥善保存。":@"此文件已加密。密码只用于本次解密。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.secureTextEntry=YES;f.placeholder=@"密码";f.autocorrectionType=UITextAutocorrectionTypeNo;}];if(confirm)[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.secureTextEntry=YES;f.placeholder=@"再次输入密码";}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"确定" style:UIAlertActionStyleDefault handler:^(id action){NSString *p=a.textFields.firstObject.text;if(confirm&&(p.length<8||![p isEqual:a.textFields.lastObject.text])){AIAlert(self,@"密码不一致或过短",@"请重新设置至少 8 个字符的相同密码。");return;}completion(p);}]];[self presentViewController:a animated:YES completion:nil];
}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(self.busy)return;if(i.section==0){NSString *key=DXBackupCategories()[i.row][@"id"];if(self.restore&&self.inspection&&![self.inspection[@"manifest"][@"categories"] containsObject:key])return;if([self.selected containsObject:key])[self.selected removeObject:key];else[self.selected addObject:key];[self updateSummary];[t reloadData];return;}if(i.section==2){[self history];return;}if(self.restore){UIDocumentPickerViewController *picker=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeData] asCopy:YES];picker.delegate=self;[self presentViewController:picker animated:YES completion:nil];}else if(i.row==1)[self askPassword:YES completion:^(NSString *p){[self usePassword:p];[t reloadData];}];}
- (void)startWork:(NSString *)title{[self.timer invalidate];self.busy=YES;self.measuredWork=[title isEqual:@"正在创建备份"];self.startedAt=NSProcessInfo.processInfo.systemUptime;self.progress=[NSProgress progressWithTotalUnitCount:self.measuredWork?1000:1];[self.progress setUserInfoObject:title forKey:@"DXBackupStage"];self.progress.completedUnitCount=0;[self updateSummary];[self.tableView layoutIfNeeded];[self viewDidLayoutSubviews];CGFloat bottom=MAX(-self.tableView.adjustedContentInset.top,self.tableView.contentSize.height-self.tableView.bounds.size.height+self.tableView.adjustedContentInset.bottom);[self.tableView setContentOffset:CGPointMake(0,bottom) animated:!UIAccessibilityIsReduceMotionEnabled()];__weak typeof(self) weak=self;self.timer=[NSTimer scheduledTimerWithTimeInterval:.2 repeats:YES block:^(NSTimer *timer){typeof(self) page=weak;if(!page){[timer invalidate];return;}[page updateWorkPanel];}];}
- (void)finishWork:(NSError *)error{[self.timer invalidate];self.timer=nil;self.busy=NO;self.progressView.progress=error?0:1;[self updateSummary];if(error){self.status.text=error.localizedDescription;AIAlert(self,@"未完成",error.localizedDescription);}}
- (void)run{
 if(self.busy&&self.observingTask){UIAlertController *confirm=[UIAlertController alertControllerWithTitle:@"终止正在进行的备份？" message:@"未完成的备份不会保存，已有备份不受影响。" preferredStyle:UIAlertControllerStyleAlert];[confirm addAction:[UIAlertAction actionWithTitle:@"继续备份" style:UIAlertActionStyleCancel handler:nil]];[confirm addAction:[UIAlertAction actionWithTitle:@"终止备份" style:UIAlertActionStyleDestructive handler:^(id action){[DXBackupTask.shared cancel];[self updateSummary];self.status.text=@"正在终止备份并清理临时文件…";}]];[self presentViewController:confirm animated:YES completion:nil];return;}
 if(self.busy)return;if(!self.selected.count){AIAlert(self,@"请选择数据分类",@"至少选择一项。");return;}
 if(self.restore){if(!self.inspection){AIAlert(self,@"请先选择备份",@"点击选择备份文件，完成校验后再恢复。");return;}UIAlertController *a=[UIAlertController alertControllerWithTitle:@"恢复所选数据？" message:@"重启后合并恢复，覆盖同名文件，保留未包含的内容。恢复前保留原文件副本。请先结束当前 AI 与构建任务。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"安排恢复" style:UIAlertActionStyleDestructive handler:^(id action){if(TFAIHasLiveRuns()||TMCGitLease.hasActiveBuilds){AIAlert(self,@"任务仍在运行",@"请等待 AI 与构建结束后恢复。");return;}[self startWork:@"正在安排恢复"];NSDictionary *inspection=self.inspection;NSSet *selected=self.selected.copy;dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;BOOL ok=DXBackupSchedule(NSHomeDirectory(),inspection,selected,&error);dispatch_async(dispatch_get_main_queue(),^{[self finishWork:error];if(ok){self.status.text=@"恢复已安排，请完全退出并重新打开 Dylix。";AIAlert(self,@"重启后恢复",self.status.text);}});});}]];[self presentViewController:a animated:YES completion:nil];return;}
 if(self.encrypted&&!self.password.length){[self askPassword:YES completion:^(NSString *p){[self usePassword:p];[self run];}];return;}
 [DXBackupTask.shared start:self.selected password:self.encrypted?self.password:@"" secrets:self.secrets];[self attachBackupTask];
}
- (void)backupTaskChanged:(NSNotification *)note{if(!self.isViewLoaded||!self.view.window||(self.busy&&!self.observingTask))return;[self attachBackupTask];}
- (void)attachBackupTask{
 DXBackupTask *task=DXBackupTask.shared;if(!task.busy&&!task.result&&!task.error)return;
 if(task.busy){self.restore=NO;[(UISegmentedControl *)self.navigationItem.titleView setSelectedSegmentIndex:0];[self.timer invalidate];self.timer=nil;[self startWork:@"正在创建备份"];self.observingTask=YES;self.progress=task.progress;self.startedAt=task.startedAt;[self updateSummary];[self.tableView reloadData];return;}
 if(!self.observingTask&&!task.result&&!task.error)return;self.observingTask=NO;[self finishWork:nil];self.progress=task.progress;self.startedAt=task.startedAt;
 if(task.error){self.progressView.hidden=YES;self.status.text=task.progress.cancelled?@"备份已终止，已有备份不受影响。":task.error.localizedDescription;if(!task.progress.cancelled&&!self.presentedViewController&&self.view.window&&[task claimCompletionNotification]){self.shownError=task.error;AIAlert(self,@"备份未完成",self.status.text);}return;}
 NSDictionary *result=task.result;NSTimeInterval elapsed=task.finishedAt-task.startedAt;NSNumber *bytes=[NSFileManager.defaultManager attributesOfItemAtPath:[result[@"url"] path] error:nil][NSFileSize];self.progressView.hidden=NO;self.progressView.progress=1;self.status.text=[NSString stringWithFormat:@"备份完成 · 100%% · %@\n用时 %@，已保存到本机备份。",[NSByteCountFormatter stringFromByteCount:bytes.longLongValue countStyle:NSByteCountFormatterCountStyleFile],[self duration:elapsed]];
 if(self.presentedViewController||!self.view.window||![task claimCompletionNotification])return;self.shownResult=result;UIAlertController *done=[UIAlertController alertControllerWithTitle:@"备份完成" message:self.status.text preferredStyle:UIAlertControllerStyleAlert];[done addAction:[UIAlertAction actionWithTitle:@"保存或分享" style:UIAlertActionStyleDefault handler:^(id action){[self share:result[@"url"]];}]];[done addAction:[UIAlertAction actionWithTitle:@"完成" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:done animated:YES completion:nil];
}

- (void)share:(NSURL *)url{UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[url] applicationActivities:nil];share.popoverPresentationController.sourceView=self.actionButton;share.popoverPresentationController.sourceRect=self.actionButton.bounds;[self presentViewController:share animated:YES completion:nil];}
- (void)inspect:(NSURL *)url password:(NSString *)password{
 [self startWork:@"正在校验备份"];dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;NSDictionary *result=DXBackupInspect(url,password,self.progress,&error);dispatch_async(dispatch_get_main_queue(),^{[self finishWork:error];if(result){if(self.inspection)[NSFileManager.defaultManager removeItemAtPath:[self.inspection[@"tree"] stringByDeletingLastPathComponent] error:nil];self.inspection=result;self.selected=[NSMutableSet setWithArray:result[@"manifest"][@"categories"]];self.status.text=@"备份校验通过，请选择分类后点击底部恢复按钮。";[self updateSummary];[self.tableView reloadData];}});});
}
- (void)documentPicker:(UIDocumentPickerViewController *)picker didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{
 NSURL *url=urls.firstObject;if(!url)return;void(^next)(void)=^{[self startWork:@"正在读取备份文件"];dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{BOOL scoped=[url startAccessingSecurityScopedResource];__block NSData *magic=nil;__block NSError *failure=nil;NSFileCoordinator *coordinator=[NSFileCoordinator new];[coordinator coordinateReadingItemAtURL:url options:0 error:&failure byAccessor:^(NSURL *local){NSFileHandle *f=[NSFileHandle fileHandleForReadingFromURL:local error:&failure];if(f){magic=[f readDataUpToLength:8 error:&failure];[f closeFile];}}];if(scoped)[url stopAccessingSecurityScopedResource];dispatch_async(dispatch_get_main_queue(),^{[self finishWork:failure];if(failure)return;if([magic isEqual:[@"DYLBAK01" dataUsingEncoding:NSUTF8StringEncoding]])[self askPassword:NO completion:^(NSString *p){[self inspect:url password:p];}];else[self inspect:url password:@""];});});};if(self.presentedViewController==picker)[picker dismissViewControllerAnimated:YES completion:next];else dispatch_async(dispatch_get_main_queue(),next);
}
- (void)history{DXLocalBackupsPage *page=[[DXLocalBackupsPage alloc]initWithStyle:UITableViewStyleInsetGrouped];[self.navigationController pushViewController:page animated:YES];}

@end
UIViewController *DXBackupController(void){return [[DXBackupPage alloc]initWithStyle:UITableViewStyleInsetGrouped];}
